#include "rocks/mesh.hpp"
#include <array>
#include <map>
#include <set>
#include <numeric>
namespace rocks {
Report validate(const Mesh&m,double size){Report r;auto error=[&](const std::string&s){r.errors.push_back(s);};auto n=m.positions.size();if(n==0||m.indices.empty()||m.indices.size()%3||m.normals.size()!=n||m.resistance.size()!=n){error("empty/mismatched mesh arrays");return r;}for(std::size_t i=0;i<n;i++)if(!finite(m.positions[i])||!finite(m.normals[i])||std::abs(length(m.normals[i])-1)>1e-6||!std::isfinite(m.resistance[i])||m.resistance[i]<0||m.resistance[i]>1){error("nonfinite/nonunit attribute");return r;}if(!m.cornerNormals.empty()){if(m.cornerNormals.size()!=m.indices.size()){error("corner-normal count mismatch");return r;}for(auto normal:m.cornerNormals)if(!finite(normal)||std::abs(length(normal)-1)>1e-6){error("invalid corner normal");return r;}}for(auto i:m.indices)if(i>=n){error("index outside mesh");return r;}
 struct Edge{int count=0,direction=0;};std::map<std::pair<unsigned,unsigned>,Edge> es;std::set<std::array<unsigned,3>> fs;std::vector<std::map<unsigned,std::vector<unsigned>>> links(n);std::vector<unsigned> parent(n);std::iota(parent.begin(),parent.end(),0);auto root=[&](unsigned i){while(parent[i]!=i){parent[i]=parent[parent[i]];i=parent[i];}return i;};std::vector<Vec3> sums(n);
 for(std::size_t i=0;i<m.indices.size();i+=3){unsigned a=m.indices[i],b=m.indices[i+1],c=m.indices[i+2];std::array<unsigned,3> face{a,b,c};auto canonical=face;std::sort(canonical.begin(),canonical.end());if(!fs.insert(canonical).second)r.duplicateFaces++;Vec3 fn=cross(m.positions[b]-m.positions[a],m.positions[c]-m.positions[a]);if(!m.cornerNormals.empty())for(int k=0;k<3;k++)if(dot(fn,m.cornerNormals[i+k])<=0)error("reversed corner normal");if(length(fn)*.5<=1e-12*size*size)r.degenerateFaces++;r.signedVolume+=dot(m.positions[a],cross(m.positions[b],m.positions[c]))/6;for(auto v:face)sums[v]=sums[v]+fn;
 for(int k=0;k<3;k++){unsigned v=face[k],w=face[(k+1)%3],u=face[(k+2)%3];auto &e=es[std::minmax(v,w)];e.count++;e.direction+=v<w?1:-1;parent[root(v)]=root(w);links[v][w].push_back(u);links[v][u].push_back(w);}}
 for(auto&[key,e]:es)if(e.count!=2||e.direction!=0)r.badEdges++;
 std::set<unsigned> roots;for(unsigned v=0;v<n;v++){roots.insert(root(v));auto &l=links[v];bool bad=l.empty();for(auto&[k,adj]:l)if(adj.size()!=2)bad=true;std::set<unsigned> seen;std::vector<unsigned> todo;if(!l.empty())todo.push_back(l.begin()->first);while(!todo.empty()){auto k=todo.back();todo.pop_back();if(!seen.insert(k).second)continue;for(auto j:l[k])if(!seen.contains(j))todo.push_back(j);}if(seen.size()!=l.size())bad=true;if(dot(sums[v],m.normals[v])<=0)bad=true;if(bad)r.badVertices++;}
 r.components=roots.size();if(r.components!=1)error("mesh must have one component");if(r.badEdges)error("unpaired/inconsistently oriented edges: "+std::to_string(r.badEdges));if(r.badVertices)error("noncircular vertex link or reversed normal: "+std::to_string(r.badVertices));if(r.degenerateFaces)error("degenerate faces: "+std::to_string(r.degenerateFaces));if(r.duplicateFaces)error("duplicate faces");if(!(r.signedVolume>1e-12*size*size*size))error("nonpositive/nearzero volume");r.accepted=r.errors.empty();return r;
}
}
